{
  "implementation": "def solve(case):
    segments = case['segments']
    n = len(segments)
    minima = [seg['minimum'] for seg in segments]
    capacities = [seg['capacity'] for seg in segments]
    allocations = list(minima)
    total_alloc = sum(allocations)
    budget = case['budget']
    while total_alloc < budget:
        best_idx = -1
        best_val = -float('inf')
        for i in range(n):
            if allocations[i] < capacities[i]:
                val = segments[i]['importance'] / (allocations[i] + 1)
                if val > best_val or (val == best_val and i < best_idx):
                    best_val = val
                    best_idx = i
        if best_idx == -1:
            break
        allocations[best_idx] += 1
        total_alloc += 1
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    return {'allocations': allocations, 'by_name': by_name, 'total': total_alloc}"
}
